package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.*;
import static org.jlinalg.cli.FollowupSupport.hash;

/** Native original-style motif enrichment from explicit captured motif/query/background inputs. */
public final class SignacMotifsRequestCli {
    private SignacMotifsRequestCli() { }
    private static final List<String> INPUTS=List.of("motif_matrix","peak_features","motif_labels","query","background");
    private static final Set<String> ALLOWED=Set.of("schema_version","mode","profile","out","genome_build","motif_collection","motif_matrix","peak_features","motif_labels","query","background","p_adjust_method","maximum_work");
    private static final String ACTION="Read WARNINGS.md, enrichment.tsv, diagnostics.json and the captured request/inputs. Preserve every attempt. Correct named input/identity/capacity causes and use NEW output paths. Review source background-alone hypergeometric inference, nonfinite rows, complete correction family and motif/reference provenance. This native operation uses explicit prepared backgrounds; sequence scanning, KDE background matching and chromVAR require separately validated upstream workflows. Unavailable upstream dependencies mean SKIP3 for those dependent analyses; install/provide exact requirements only where permitted. A failed verification is not an admitted result.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(out,"SignacMotifsRequestCli --request ASCII_PATH_TO_UTF8_JSON\nModes: ENRICH (explicit prepared query/background) or VERIFY (no R). Relative paths resolve against the request directory.\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON");Path path=Path.of(args[1]).toAbsolutePath().normalize();Map<String,Object> request=read(path);schema(request);
            if("VERIFY".equals(request.get("mode"))){keys(request,Set.of("schema_version","mode","analysis"));verify(resolve(path.getParent(),text(request,"analysis"),false));emit(out,"Verified captured native motif counts, statistics, correction family, ordering and warnings; upstream selection provenance is separate");return 0;}
            validate(request);Path destination=resolve(path.getParent(),text(request,"out"),false);int[] code={0};
            FollowupSupport.externalTransaction(Map.of("out",destination.toString()),"signac-native-motif-enrichment-development",(stage,manifest)->{
                List<String> warnings=new ArrayList<>();try{
                    String before=hash(path);Files.copy(path,stage.resolve("source-request.json"));if(!before.equals(hash(path))||!before.equals(hash(stage.resolve("source-request.json"))))throw new IOException("Request changed during capture");Map<String,Object> captured=capture(request,path.getParent(),stage);json(stage.resolve("request.json"),captured);Prepared prepared=prepare(captured,stage);warnings.addAll(prepared.warnings);writeTable(stage.resolve("enrichment.tsv"),prepared.result,profile(captured)==SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS);json(stage.resolve("diagnostics.json"),diagnostics(prepared));manifest.put("analysis_status","completed-with-warnings");manifest.put("mode","ENRICH");manifest.put("profile",captured.get("profile"));manifest.put("source_request_sha256",before);manifest.put("upstream_background_selection_performed",false);manifest.put("sequence_scanning_performed",false);manifest.put("full_Signac_workflow_available",false);
                }catch(Exception failure){code[0]=2;manifest.put("analysis_status","failed");manifest.put("error",failure.toString());warnings.add("FAIL2 — NO MOTIF RESULT ADMITTED: "+failure);if(Files.exists(stage.resolve("enrichment.tsv")))Files.move(stage.resolve("enrichment.tsv"),stage.resolve("retained-partial-enrichment.tsv"));}
                Files.writeString(stage.resolve("WARNINGS.md"),warningText(warnings,code[0]),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);json(stage.resolve("analysis-status.json"),Map.of("status",manifest.get("analysis_status")));json(stage.resolve("manifest.json"),manifest);
            });seal(destination);if(code[0]==0){verify(destination);emit(out,"Completed native motif enrichment: "+destination);}else emit(err,"FAIL2 — NO MOTIF RESULT ADMITTED: "+destination);emit(err,"WARNINGS / REQUIRED ACTION: "+destination.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        }catch(Exception failure){emit(err,"FAIL2 — Native motif request/verification failed: "+failure+"\n"+ACTION);return 2;}
    }
    private static void validate(Map<String,Object> r)throws IOException{
        schema(r);keys(r,ALLOWED);if(!"ENRICH".equals(r.get("mode")))throw new IOException("Require ENRICH or VERIFY mode");if(!Set.of("1.6.0-source","1.9.0-source","1.14.0-source","1.17.1-package").contains(text(r,"profile")))throw new IOException("Choose a supported explicit source-statistics profile");
        for(String key:List.of("out","genome_build","motif_collection","motif_matrix","peak_features","motif_labels","query"))text(r,key);if(r.get("background")!=null)text(r,"background");correction(r);work(r);
    }
    private record Prepared(SignacMotifIO.Input input,SignacMotifEnrichment.Result result,List<String> warnings) { }
    private static Prepared prepare(Map<String,Object> r,Path root)throws IOException{
        validate(r);var input=SignacMotifIO.read(input(r,"motif_matrix",root),input(r,"peak_features",root),input(r,"motif_labels",root),SignacMotifIO.Limits.defaults(),()->Thread.currentThread().isInterrupted());var query=selection(input(r,"query",root));var background=r.get("background")==null?null:selection(input(r,"background",root));var result=SignacMotifEnrichment.enrich(input.matrix(),query,background,profile(r),correction(r),work(r),()->Thread.currentThread().isInterrupted());List<String> warnings=new ArrayList<>();
        warnings.add("EXPLICIT_PREPARED_INPUTS: motif_collection and genome_build are declarations, not certification. Review motif matrix/scanning thresholds, database edition, reference assembly and the supplied query/background selections. No sequence scan, GC computation, KDE matching or chromVAR calculation was performed.");
        if(input.duplicateCoordinates()>0)warnings.add("DUPLICATE_MATRIX_COORDINATES: "+input.duplicateCoordinates()+" duplicates were combined using "+(input.field().equals("pattern")?"logical pattern union":"exact numeric count sums")+"; explicit numeric zeros remain stored. Review source storage provenance.");
        warnings.addAll(result.warnings());return new Prepared(input,result,List.copyOf(warnings));
    }
    private static List<String> selection(Path path)throws IOException{
        if(!Files.isRegularFile(path)||Files.size(path)>2_000_000_000L)throw new IOException("Selected-peak file missing or excessive");List<String> values=new ArrayList<>();
        try(var in=new BufferedReader(new InputStreamReader(Files.newInputStream(path),StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)))){
            for(;;){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException();StringBuilder value=new StringBuilder();int c;while((c=in.read())>=0&&c!='\n'){if(value.length()>=4094)throw new IOException("Selected-peak identity exceeds capacity");value.append((char)c);}if(c<0&&value.isEmpty())break;if(!value.isEmpty()&&value.charAt(value.length()-1)=='\r')value.setLength(value.length()-1);String id=value.toString();if(id.isBlank()||id.indexOf('\t')>=0||id.indexOf(0)>=0||values.size()>=2_000_000)throw new IOException("Malformed/excessive selected peak IDs; use no header and no blank lines");values.add(id);if(c<0)break;}
        }return List.copyOf(values);
    }
    private static Map<String,Object> capture(Map<String,Object> r,Path parent,Path stage)throws IOException{
        Map<String,Object> captured=new LinkedHashMap<>(r);captured.put("out",".");Path folder=Files.createDirectory(stage.resolve("input"));int index=0;
        for(String key:INPUTS)if(r.get(key)!=null){Path source=resolve(parent,text(r,key),false);if(!Files.isRegularFile(source)||Files.size(source)>2_000_000_000L)throw new IOException("Missing/excessive motif input: "+key);String name="file-"+index++;Path target=folder.resolve(name);String before=hash(source);Files.copy(source,target);if(!before.equals(hash(source))||!before.equals(hash(target)))throw new IOException("Motif input changed during capture: "+key);captured.put(key,"input/"+name);}return captured;
    }
    private static Map<String,Object> diagnostics(Prepared p){var r=p.result;return Map.of("motifs",r.rows().size(),"query_rows",r.queryRows(),"background_rows",r.backgroundRows(),"repeated_query_rows",r.repeatedQueryRows(),"repeated_background_rows",r.repeatedBackgroundRows(),"sparse_work",r.work(),"matrix_field",p.input.field(),"duplicate_matrix_coordinates",p.input.duplicateCoordinates());}
    private static String header(boolean adjusted){return "motif\tobserved\tbackground\tpercent.observed\tpercent.background\tfold.enrichment\tpvalue\tmotif.name"+(adjusted?"\tp.adjust":"");}
    private static String row(SignacMotifEnrichment.Row r){return r.motif()+"\t"+number(r.observed())+"\t"+number(r.background())+"\t"+number(r.percentObserved())+"\t"+number(r.percentBackground())+"\t"+number(r.foldEnrichment())+"\t"+number(r.pvalue())+"\t"+r.name()+(r.adjustedP()==null?"":"\t"+number(r.adjustedP()));}
    private static String number(double value){return Double.isNaN(value)?"NaN":value==Double.POSITIVE_INFINITY?"Inf":value==Double.NEGATIVE_INFINITY?"-Inf":Double.toString(value);}
    private static void writeTable(Path path,SignacMotifEnrichment.Result result,boolean adjusted)throws IOException{try(var out=Files.newBufferedWriter(path,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){out.write(header(adjusted)+"\n");for(var r:result.rows())out.write(row(r)+"\n");}}
    private static void tableMatches(Path path,SignacMotifEnrichment.Result result,boolean adjusted)throws IOException{try(var in=Files.newBufferedReader(path,StandardCharsets.UTF_8)){if(!Objects.equals(in.readLine(),header(adjusted)))throw new IOException("Motif result header changed");for(var r:result.rows())if(!Objects.equals(in.readLine(),row(r)))throw new IOException("Native motif row/statistic/order changed");if(in.readLine()!=null)throw new IOException("Excess motif result rows");}}
    private static String warningText(List<String> warnings,int code){return (code==0?"# WARNINGS / REQUIRED ACTIONS — NATIVE MOTIF ENRICHMENT\n":"# FAIL2 — NO MOTIF RESULT ADMITTED\n")+"\n"+String.join("\n\n",new LinkedHashSet<>(warnings))+"\n\nRequired action: "+ACTION+"\n";}
    private static void seal(Path root)throws IOException{Path inventory=root.resolve("artifact-checksums.tsv");try(var out=Files.newBufferedWriter(inventory,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);var files=Files.walk(root)){out.write("sha256\tpath\n");for(Path p:files.filter(Files::isRegularFile).filter(p->!p.equals(inventory)).sorted().toList())out.write(hash(p)+"\t"+root.relativize(p).toString().replace('\\','/')+"\n");}}
    private static void verify(Path root)throws IOException{
        Path inventory=root.resolve("artifact-checksums.tsv");if(!Files.isRegularFile(inventory)||Files.size(inventory)>10_000_000)throw new IOException("Missing/excessive motif inventory");List<String> lines=Files.readAllLines(inventory,StandardCharsets.UTF_8);if(lines.isEmpty()||!lines.get(0).equals("sha256\tpath"))throw new IOException("Missing motif inventory header");Set<String> seen=new HashSet<>();
        for(String line:lines.subList(1,lines.size())){String[] f=line.split("\t",-1);if(f.length!=2||!f[0].matches("[0-9a-f]{64}")||f[1].contains(":")||f[1].contains("\\")||Arrays.stream(f[1].split("/",-1)).anyMatch(v->Set.of("",".","..").contains(v)))throw new IOException("Unsafe motif inventory");Path p=root.resolve(f[1]);if(!seen.add(f[1])||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||!hash(p).equals(f[0]))throw new IOException("Motif artifact integrity mismatch");}
        try(var files=Files.walk(root)){for(Path p:files.toList()){if(Files.isSymbolicLink(p))throw new IOException("Captured motif symlink forbidden");if(Files.isRegularFile(p)&&!p.equals(inventory)&&!seen.contains(root.relativize(p).toString().replace('\\','/')))throw new IOException("Uninventoried motif file");}}
        Map<String,Object> manifest=read(root.resolve("manifest.json")),status=read(root.resolve("analysis-status.json"));if(!"completed-with-warnings".equals(manifest.get("analysis_status"))||!Objects.equals(status.get("status"),manifest.get("analysis_status"))||!"ENRICH".equals(manifest.get("mode")))throw new IOException("Native motif analysis did not complete");for(String key:List.of("upstream_background_selection_performed","sequence_scanning_performed","full_Signac_workflow_available"))if(!Boolean.FALSE.equals(manifest.get(key)))throw new IOException("Native motif scope declaration changed");
        Map<String,Object> original=read(root.resolve("source-request.json")),current=read(root.resolve("request.json"));validate(original);Map<String,Object> expected=new LinkedHashMap<>(original);expected.put("out",".");int index=0;for(String key:INPUTS)if(original.get(key)!=null)expected.put(key,"input/file-"+index++);if(!expected.equals(current)||!Objects.equals(manifest.get("source_request_sha256"),hash(root.resolve("source-request.json")))||!Objects.equals(manifest.get("profile"),current.get("profile")))throw new IOException("Native motif request binding changed");
        Prepared p=prepare(current,root);if(!NextflowJson.json(diagnostics(p)).equals(NextflowJson.json(read(root.resolve("diagnostics.json")))))throw new IOException("Native motif diagnostics changed");tableMatches(root.resolve("enrichment.tsv"),p.result,profile(current)==SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS);if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText(p.warnings,0)))throw new IOException("Native motif warnings/actions changed");
    }
    private static SignacMotifEnrichment.Profile profile(Map<String,Object> r){return r.get("profile").equals("1.6.0-source")?SignacMotifEnrichment.Profile.LEGACY_1_6:SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS;}
    private static SignacMotifEnrichment.Correction correction(Map<String,Object> r)throws IOException{Object v=r.getOrDefault("p_adjust_method","BH");if(!(v instanceof String method)||method.isBlank())throw new IOException("Require a correction method string");if(profile(r)==SignacMotifEnrichment.Profile.LEGACY_1_6)return SignacMotifEnrichment.Correction.NONE;if(!Set.of("BH","BY","holm","hochberg","hommel","bonferroni","none","fdr").contains(method))throw new IOException("Choose BH,BY,holm,hochberg,hommel,bonferroni,none or fdr");return SignacMotifEnrichment.Correction.valueOf(method.equals("fdr")?"BH":method.toUpperCase(Locale.ROOT));}
    private static long work(Map<String,Object> r)throws IOException{Object v=r.getOrDefault("maximum_work",100_000_000L);if(!(v instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=Math.rint(n.doubleValue())||n.doubleValue()<1||n.doubleValue()>10_000_000_000_000L)throw new IOException("maximum_work must be an integer from1 to1e13");return n.longValue();}
    private static void schema(Map<String,Object> r)throws IOException{if(!(r.get("schema_version") instanceof Number n)||n.doubleValue()!=1)throw new IOException("Require schema_version1");}
    private static void keys(Map<String,Object> r,Set<String> allowed)throws IOException{for(String key:r.keySet())if(!allowed.contains(key))throw new IOException("Unknown motif request field: "+key);}
    private static String text(Map<String,Object> r,String key)throws IOException{if(!(r.get(key) instanceof String v)||v.isBlank())throw new IOException("Require nonblank field: "+key);return v;}
    private static Path resolve(Path parent,String value,boolean captured)throws IOException{Path path=parent.resolve(Path.of(value)).toAbsolutePath().normalize();if(captured&&(!path.startsWith(parent)||Files.isSymbolicLink(path)))throw new IOException("Captured motif input escapes analysis");return path;}
    private static Path input(Map<String,Object> r,String key,Path root)throws IOException{return resolve(root,text(r,key),true);}
    private static Map<String,Object> read(Path path)throws IOException{if(!Files.isRegularFile(path)||Files.size(path)>1_000_000)throw new IOException("Motif JSON unavailable/excessive");Object value=SimpleJson.parse(Files.readString(path,StandardCharsets.UTF_8));if(!(value instanceof Map<?,?> map))throw new IOException("Expected motif JSON object");Map<String,Object> result=new LinkedHashMap<>();for(var e:map.entrySet())result.put((String)e.getKey(),e.getValue());return result;}
    private static void json(Path path,Map<String,Object> value)throws IOException{Files.writeString(path,NextflowJson.json(value),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}
    private static void emit(PrintStream out,String value){out.writeBytes((value+"\n").getBytes(StandardCharsets.UTF_8));}
}
